/**
 * Wave 3 games — make RuneScape: Dragonwilds, Sunkenland, Abiotic Factor,
 * Core Keeper and Icarus orderable. Same Docker/OsTemplate pattern as Waves 1-2:
 * each is a community Docker image (wrapping SteamCMD, +Wine where the game's
 * dedicated-server build is Windows-only) installed by the OsTemplate.setupScript
 * in cloud-init. Researched 2026-08-31 against each game's official dedicated-
 * server docs / SteamDB — all five have real, currently-shipping dedicated
 * server support (none are P2P/lobby-only, unlike schedule1 which stays
 * unseeded — see lib/games.ts and lib/game-control.ts comments).
 *
 * Steam App IDs (dedicated server, NOT the game client):
 *   dragonwilds     4019830  (RuneScape: Dragonwilds Dedicated Server — native Linux)
 *   sunkenland      2667530  (Sunkenland Dedicated Server — Windows-only, Wine image)
 *   abioticfactor   2857200  (Abiotic Factor Dedicated Server — Windows-only, Wine image)
 *   corekeeper      1963720  (Core Keeper Dedicated Server — native Linux)
 *   icarus          2089300  (Icarus Dedicated Server — Windows-only, Wine image)
 *
 * Docker images picked to match publishers ALREADY trusted elsewhere in this
 * catalog where possible (same continuity as Waves 1-2 picking one community
 * image per game): indifferentbroccoli (already projectzomboid), melle2
 * (already conan), mornedhels (already enshrouded). Core Keeper and Abiotic
 * Factor use the most widely-referenced community images for their game
 * (escapingnetwork, Pleut) since no already-used publisher ships those.
 *
 * NOTE: static in-container placeholder passwords ("changeme12"/blank) — customers
 * change them post-deploy, matching every prior wave. Dragonwilds' OWNER_ID (the
 * server owner's Steam64 id, grants in-game admin) is a genuinely per-customer
 * value with no sane platform default — seeded as "0" (server boots fine without
 * it; only affects who can already issue admin commands) with a hint in
 * ADMIN_PASSWORD for the customer to set OWNER_ID post-deploy via SFTP.
 *
 * Run: cd /opt/nxeon && npx tsx prisma/seed-wave3-games.ts   (idempotent)
 */
import { PrismaClient } from "@prisma/client";

const db = new PrismaClient();

type Template = { family: string; name: string; setupScript: string; minRamMB: number; minDiskGB: number };

const TEMPLATES: Template[] = [
  {
    family: "dragonwilds", name: "RuneScape: Dragonwilds Server", minRamMB: 4096, minDiskGB: 20,
    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/dragonwilds && docker run -d --name dragonwilds --restart unless-stopped --stop-timeout 30 -p 7777:7777/udp -e OWNER_ID='0' -e ADMIN_PASSWORD='changeme12' -e SERVER_NAME='Nxeon' -e DEFAULT_PORT='7777' -e MAX_PLAYERS='6' -v /opt/dragonwilds:/home/steam/server-files indifferentbroccoli/runescape-dragonwilds-server-docker:latest`,
  },
  {
    family: "sunkenland", name: "Sunkenland Server", minRamMB: 4096, minDiskGB: 20,
    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/sunkenland/Worlds /opt/sunkenland/game /opt/sunkenland/Steam && docker run -d --name sunkenland --restart unless-stopped -p 27015:27015/udp -p 27016:27016/udp -e GAME_WORLD_GUID='nxeon-world' -v /opt/sunkenland/Worlds:/sunkenland/Worlds -v /opt/sunkenland/game:/sunkenland/game -v /opt/sunkenland/Steam:/sunkenland/Steam melle2/sunkenland-ds:latest`,
  },
  {
    family: "abioticfactor", name: "Abiotic Factor Server", minRamMB: 6144, minDiskGB: 25,
    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/abioticfactor/gamefiles /opt/abioticfactor/data && docker run -d --name abioticfactor --restart unless-stopped -p 7777:7777/udp -p 27015:27015/udp -e MaxServerPlayers='6' -e Port='7777' -e QueryPort='27015' -e ServerPassword='changeme12' -e SteamServerName='Nxeon' -e WorldSaveName='Cascade' -v /opt/abioticfactor/gamefiles:/server -v /opt/abioticfactor/data:/server/AbioticFactor/Saved ghcr.io/pleut/abiotic-factor-linux-docker:latest`,
  },
  {
    family: "corekeeper", name: "Core Keeper Server", minRamMB: 2048, minDiskGB: 15,
    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/corekeeper/data /opt/corekeeper/files && docker run -d --name corekeeper --restart unless-stopped -p 27015:27015/udp -e WORLD_NAME='Nxeon Core Keeper' -e MAX_PLAYERS='8' -e SERVER_PORT='27015' -v /opt/corekeeper/data:/home/steam/core-keeper-data -v /opt/corekeeper/files:/home/steam/core-keeper-dedicated escaping/core-keeper-dedicated:latest`,
  },
  {
    family: "icarus", name: "Icarus Server", minRamMB: 6144, minDiskGB: 30,
    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/icarus/data /opt/icarus/game && docker run -d --name icarus --hostname icarus --restart unless-stopped --stop-timeout 90 -p 17777:17777/udp -p 27015:27015/udp -e SERVER_NAME='Nxeon' -e SERVER_PASSWORD='' -e SERVER_ADMIN_PASSWORD='changeme12' -e SERVER_PORT='17777' -e SERVER_QUERYPORT='27015' -e PUID='4711' -e PGID='4711' -v /opt/icarus/data:/home/icarus/drive_c/icarus -v /opt/icarus/game:/opt/icarus mornedhels/icarus-server:latest`,
  },
];

type TierSpec = { gameFamily: string; name: string; ramMB: number; cpuCores: number; diskGB: number; slots: number; priceCents: number; featured?: boolean };

const TIERS: TierSpec[] = [
  // Dragonwilds — hard-capped at 6 players; official spec is 2 GB + 1 GB/player.
  { gameFamily: "dragonwilds", name: "Dragonwilds — 4 GB / 3 players", ramMB: 4096, cpuCores: 2, diskGB: 20, slots: 3, priceCents: 899 },
  { gameFamily: "dragonwilds", name: "Dragonwilds — 6 GB / 5 players", ramMB: 6144, cpuCores: 2, diskGB: 25, slots: 5, priceCents: 1299, featured: true },
  { gameFamily: "dragonwilds", name: "Dragonwilds — 8 GB / 6 players", ramMB: 8192, cpuCores: 3, diskGB: 30, slots: 6, priceCents: 1699 },

  // Sunkenland — small-party raft/island survival, similar scale to Valheim/Enshrouded.
  { gameFamily: "sunkenland", name: "Sunkenland — 4 GB / 4 players", ramMB: 4096, cpuCores: 2, diskGB: 20, slots: 4, priceCents: 899 },
  { gameFamily: "sunkenland", name: "Sunkenland — 6 GB / 8 players", ramMB: 6144, cpuCores: 3, diskGB: 30, slots: 8, priceCents: 1399, featured: true },
  { gameFamily: "sunkenland", name: "Sunkenland — 8 GB / 10 players", ramMB: 8192, cpuCores: 4, diskGB: 40, slots: 10, priceCents: 1899 },

  // Abiotic Factor — Wine-based like Enshrouded, small co-op teams.
  { gameFamily: "abioticfactor", name: "Abiotic Factor — 6 GB / 4 players", ramMB: 6144, cpuCores: 2, diskGB: 25, slots: 4, priceCents: 1199 },
  { gameFamily: "abioticfactor", name: "Abiotic Factor — 8 GB / 6 players", ramMB: 8192, cpuCores: 3, diskGB: 35, slots: 6, priceCents: 1699, featured: true },
  { gameFamily: "abioticfactor", name: "Abiotic Factor — 12 GB / 8 players", ramMB: 12288, cpuCores: 4, diskGB: 45, slots: 8, priceCents: 2299 },

  // Core Keeper — lightweight 2D sandbox, native Linux; official cap is 8 players.
  { gameFamily: "corekeeper", name: "Core Keeper — 2 GB / 6 players", ramMB: 2048, cpuCores: 1, diskGB: 15, slots: 6, priceCents: 499 },
  { gameFamily: "corekeeper", name: "Core Keeper — 4 GB / 8 players", ramMB: 4096, cpuCores: 2, diskGB: 25, slots: 8, priceCents: 799, featured: true },
  { gameFamily: "corekeeper", name: "Core Keeper — 6 GB / 8 players", ramMB: 6144, cpuCores: 2, diskGB: 35, slots: 8, priceCents: 1199 },

  // Icarus — Wine-based like Enshrouded, procedural-planet co-op prospects.
  { gameFamily: "icarus", name: "Icarus — 6 GB / 4 players", ramMB: 6144, cpuCores: 2, diskGB: 30, slots: 4, priceCents: 1299 },
  { gameFamily: "icarus", name: "Icarus — 8 GB / 8 players", ramMB: 8192, cpuCores: 3, diskGB: 40, slots: 8, priceCents: 1899, featured: true },
  { gameFamily: "icarus", name: "Icarus — 12 GB / 8 players", ramMB: 12288, cpuCores: 4, diskGB: 50, slots: 8, priceCents: 2499 },
];

async function main() {
  const templateIdByFamily = new Map<string, string>();
  let sort = 50;
  for (const t of TEMPLATES) {
    const os = await db.osTemplate.upsert({
      where: { slug: t.family },
      create: {
        slug: t.family, name: t.name, category: "APPLICATION", family: t.family, version: "", logo: t.family,
        vmid: 9000, baseVmid: 9000, setupScript: t.setupScript, minRamMB: t.minRamMB, minDiskGB: t.minDiskGB,
        licenseRequired: false, featured: false, sortOrder: sort++, active: true,
      },
      update: { name: t.name, setupScript: t.setupScript, minRamMB: t.minRamMB, minDiskGB: t.minDiskGB, active: true },
    });
    templateIdByFamily.set(t.family, os.id);
    console.log(`  osTemplate ${t.family.padEnd(16)} → ${os.id}`);
  }

  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { ramMB: "asc" } });
  if (plans.length === 0) throw new Error("No active VPS plans — run the main seed first.");
  const largest = plans[plans.length - 1];

  let created = 0, updated = 0;
  const sortByGame = new Map<string, number>();
  for (const spec of TIERS) {
    const basePlan = plans.find((p) => p.ramMB >= spec.ramMB) ?? largest;
    const osId = templateIdByFamily.get(spec.gameFamily) ?? null;
    const sortOrder = sortByGame.get(spec.gameFamily) ?? 0;
    sortByGame.set(spec.gameFamily, sortOrder + 1);
    const data = {
      gameFamily: spec.gameFamily, name: spec.name, ramMB: spec.ramMB, cpuCores: spec.cpuCores, diskGB: spec.diskGB,
      slots: spec.slots, priceCents: spec.priceCents, termMonths: 1, basePlanId: basePlan.id, osTemplateId: osId,
      featured: spec.featured ?? false, active: true, sortOrder,
    };
    const existing = await db.gamePlan.findFirst({ where: { gameFamily: spec.gameFamily, name: spec.name } });
    if (existing) { await db.gamePlan.update({ where: { id: existing.id }, data }); updated++; }
    else { await db.gamePlan.create({ data }); created++; }
    console.log(`  plan ${spec.name.padEnd(38)} base=${basePlan.name}`);
  }
  console.log(`\nWave 3: ${TEMPLATES.length} OsTemplates, GamePlans ${created} created / ${updated} updated.`);
}

main().catch((e) => { console.error(e); process.exit(1); }).finally(() => db.$disconnect());

